#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
#include <utility>
#include <functional>
using namespace std;

int main(){
vector<double> x={1,2,3,4},label={2,4,6,8};
double mse=0,center=0,nextStepLoss=0;
for(int i=0;i<int(x.size());i++){
    mse+=pow(2*x[i]-label[i],2)/x.size();
    center+=x[i]/x.size();
    if(i+1<int(x.size()))nextStepLoss+=pow(x[i]-x[i+1],2)/(x.size()-1);
}
cout<<"supervised MSE "<<mse<<" unsupervised center "<<center<<"\n";
cout<<"self-supervised next-step error "<<nextStepLoss<<"\n";
return 0;
}

