#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
#include <utility>
#include <functional>
using namespace std;

int main(){
double A[2][2]={{3,0},{0,1}};
double x=1,y=1;
for(int step=0;step<50;step++){
    double nx=9*x,ny=y,length=sqrt(nx*nx+ny*ny);
    x=nx/length;y=ny/length;
}
double singular=sqrt(9*x*x+y*y);
double reconstructionError=0;
for(int i=0;i<2;i++)for(int j=0;j<2;j++){
    double approximation=singular*(i==0?x:y)*(j==0?x:y);
    reconstructionError+=pow(A[i][j]-approximation,2);
}
cout<<"leading singular value "<<singular<<"\n";
cout<<"rank-one approximation error "<<sqrt(reconstructionError)<<"\n";
return 0;
}

