#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
#include <utility>
#include <functional>
using namespace std;

int main(){
vector<double> w={0,0},correlation={0.8,0.08};
double step=0.1,lambda=0.2;
for(int iteration=0;iteration<100;iteration++){
    for(int j=0;j<2;j++){
        double gradient=w[j]-correlation[j];
        double candidate=w[j]-step*gradient;
        double threshold=step*lambda;
        if(candidate>threshold)w[j]=candidate-threshold;
        else if(candidate< -threshold)w[j]=candidate+threshold;
        else w[j]=0;
    }
}
cout<<"selected coefficients "<<w[0]<<" "<<w[1]<<"\n";
return 0;
}

