#include <utility>
#include <functional>
using namespace std;

int main(){
vector<double> points={0,0.2,1.0,4.0,4.4};
vector<int> cluster={0,0,0,1,1};
for(int i=0;i<int(points.size());i++){
    double within=0,between=0;int same=0,other=0;
    for(int j=0;j<int(points.size());j++)if(i!=j){
        if(cluster[i]==cluster[j]){within+=fabs(points[i]-points[j]);same++;}
        else{between+=fabs(points[i]-points[j]);other++;}
    }
    double a=same?within/same:0,b=other?between/other:0;
    double silhouette=same?((b-a)/max(a,b)):0;
    cout<<i<<" silhouette "<<silhouette<<"\n";
}
return 0;
}

