#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
#include <utility>
#include <functional>
using namespace std;

int main(){
vector<double> query={1,2,0};
vector<vector<double>> documents={{2,1,0},{0,1,3},{1,2,1}};
vector<pair<double,int>> ranking;
for(int i=0;i<int(documents.size());i++){
    double dot=0,aa=0,bb=0;
    for(int j=0;j<int(query.size());j++){
        dot+=query[j]*documents[i][j];
        aa+=query[j]*query[j];bb+=documents[i][j]*documents[i][j];
    }
    ranking.push_back({dot/sqrt(aa*bb),i});
}
sort(ranking.begin(),ranking.end(),greater<pair<double,int>>());
for(const auto& item:ranking)cout<<"document "<<item.second<<" similarity "<<item.first<<"\n";
return 0;
}

