#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
#include <utility>
#include <functional>
using namespace std;

int main(){
vector<double> close={100,101,103,99,98,102,104};
int horizon=3;double up=0.02,down=-0.02;
for(int start=0;start+horizon<int(close.size());start++){
    int label=0,maturity=start+horizon;
    for(int t=start+1;t<=start+horizon;t++){
        double realized=close[t]/close[start]-1;
        if(realized>=up){label=1;maturity=t;break;}
        if(realized<=down){label=-1;maturity=t;break;}
    }
    cout<<start<<" label "<<label<<" exit "<<maturity<<"\n";
}
return 0;
}

