#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
#include <utility>
#include <functional>
using namespace std;

int main(){
vector<double> loss={0.01,0.05,0.02,0.12,0.20,0.08};
vector<int> knownMember={1,1,1,0,0,0};
double threshold=0.06;int correct=0,falsePositive=0;
for(int i=0;i<int(loss.size());i++){
    int inferred=loss[i]<threshold;
    correct+=(inferred==knownMember[i]);
    if(inferred&&!knownMember[i])falsePositive++;
}
cout<<"attack accuracy "<<double(correct)/loss.size()
    <<" non-member false positives "<<falsePositive<<"\n";
return 0;
}
